/*
 * log.hpp — Verbose logging for the Epilog runtime.
 *
 * Pass --verbose or -v on the command line to activate.
 * JPL rules: no heap, no recursion.
 */

#pragma once

#include <cstdio>
#include <cstring>
#include <cstdarg>

extern int g_verbose;

inline void log_init(int argc, char *argv[])
{
    g_verbose = 0;
    for (int i = 1; i < argc; ++i) {
        if (strncmp(argv[i], "--verbose", 10) == 0 ||
            strncmp(argv[i], "-v",         3) == 0) {
            g_verbose = 1;
        }
    }
}

inline void vlog(const char *subsys, const char *fmt, ...)
{
    if (!g_verbose) { return; }
    va_list ap;
    fprintf(stderr, "[%s] ", subsys);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
}

#define LOG_INIT(argc, argv)          log_init((argc), (argv))
#define VLOG(fmt, ...)                vlog("epilog", (fmt), __VA_ARGS__)
#define VLOG_SUBSYS(s, fmt, ...)      vlog((s),      (fmt), __VA_ARGS__)

/*
 * lexer.cpp — Tokenizer implementation.
 * JPL rules: no recursion, bounded loop, no post-init malloc.
 */

#include "../include/lexer.hpp"
#include <cstring>
#include <cassert>
#include <cstdint>

static bool is_alpha(char c)  { return (c>='a'&&c<='z')||(c>='A'&&c<='Z'); }
static bool is_digit(char c)  { return c>='0' && c<='9'; }
static bool is_lower(char c)  { return c>='a' && c<='z'; }
static bool is_upper(char c)  { return c>='A' && c<='Z'; }
static bool is_alnum(char c)  { return is_alpha(c) || is_digit(c) || c=='_'; }
static bool is_space(char c)  { return c==' '||c=='\t'||c=='\r'||c=='\n'; }

static bool is_op_char(char c)
{
    return c=='='||c=='\\'||c=='+'||c=='-'||c=='*'||c=='/'||
           c=='<'||c=='>'||c=='@'||c=='#'||c=='^'||c=='~';
}

static int append_token(TokenList *out, TokenKind kind,
                        const char *text, int32_t int_val, uint32_t line)
{
    assert(out != nullptr);
    if (out->count >= TOKEN_LIST_CAPACITY) { return -1; }

    Token *t   = &out->items[out->count];
    t->kind    = kind;
    t->int_val = int_val;
    t->line    = line;

    if (text != nullptr) {
        const size_t len = strnlen(text, TOKEN_TEXT_MAX);
        memcpy(t->text, text, len);
        t->text[len] = '\0';
    } else {
        t->text[0] = '\0';
    }
    out->count++;
    return 0;
}

int lex(const char *src, TokenList *out)
{
    if (src == nullptr || out == nullptr) { return -1; }

    memset(out, 0, sizeof(TokenList));
    const uint32_t len  = static_cast<uint32_t>(strnlen(src, 1U << 20));
    uint32_t       line = 1U;
    uint32_t       i    = 0U;
    char           buf[TOKEN_TEXT_MAX + 1U];

    while (i < len) {
        const char c = src[i];

        if (is_space(c)) { if (c == '\n') { line++; } i++; continue; }

        /* line comment */
        if (c == '%') { while (i < len && src[i] != '\n') { i++; } continue; }

        /* block comment */
        if (c == '/' && i + 1U < len && src[i + 1U] == '*') {
            uint32_t depth = 1U;
            i += 2U;
            while (i + 1U < len && depth > 0U) {
                if (src[i] == '\n')                     { line++; }
                if (src[i]=='*' && src[i+1U]=='/') { depth--; i+=2U; continue; }
                if (src[i]=='/' && src[i+1U]=='*') { depth++; i+=2U; continue; }
                i++;
            }
            continue;
        }

        /* atom: lowercase-initial */
        if (is_lower(c)) {
            uint32_t bp = 0U;
            while (i < len && is_alnum(src[i]) && bp < TOKEN_TEXT_MAX) { buf[bp++] = src[i++]; }
            buf[bp] = '\0';
            if (append_token(out, TOK_ATOM, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* variable: uppercase or underscore */
        if (is_upper(c) || c == '_') {
            uint32_t bp = 0U;
            while (i < len && is_alnum(src[i]) && bp < TOKEN_TEXT_MAX) { buf[bp++] = src[i++]; }
            buf[bp] = '\0';
            if (append_token(out, TOK_VAR, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* integer */
        if (is_digit(c)) {
            int32_t  val = 0;
            uint32_t bp  = 0U;
            while (i < len && is_digit(src[i]) && bp < TOKEN_TEXT_MAX) {
                val = val * 10 + static_cast<int32_t>(src[i] - '0');
                buf[bp++] = src[i++];
            }
            buf[bp] = '\0';
            if (append_token(out, TOK_INT, buf, val, line) < 0) { return -1; }
            continue;
        }

        /* single-quoted atom */
        if (c == '\'') {
            uint32_t bp = 0U;
            i++;
            while (i < len && src[i] != '\'' && bp < TOKEN_TEXT_MAX) {
                if (src[i] == '\n') { line++; }
                buf[bp++] = src[i++];
            }
            if (i < len) { i++; }
            buf[bp] = '\0';
            if (append_token(out, TOK_ATOM, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* two-character tokens */
        if (c == ':' && i+1U < len && src[i+1U] == '-') { append_token(out, TOK_NECK,  ":-", 0, line); i+=2U; continue; }
        if (c == '?' && i+1U < len && src[i+1U] == '-') { append_token(out, TOK_QUERY, "?-", 0, line); i+=2U; continue; }
        if (c == '\\' && i+1U < len && src[i+1U] == '=') { append_token(out, TOK_OP, "\\=", 0, line); i+=2U; continue; }

        /* operator sequences */
        if (is_op_char(c)) {
            uint32_t bp = 0U;
            while (i < len && is_op_char(src[i]) && bp < TOKEN_TEXT_MAX) { buf[bp++] = src[i++]; }
            buf[bp] = '\0';
            if (append_token(out, TOK_OP, buf, 0, line) < 0) { return -1; }
            continue;
        }

        /* single-character punctuation */
        switch (c) {
            case '(': append_token(out, TOK_LPAREN, "(", 0, line); break;
            case ')': append_token(out, TOK_RPAREN, ")", 0, line); break;
            case ',': append_token(out, TOK_COMMA,  ",", 0, line); break;
            case '.':
                if (i+1U >= len || is_space(src[i+1U]))
                    append_token(out, TOK_DOT, ".", 0, line);
                else
                    append_token(out, TOK_OP,  ".", 0, line);
                break;
            case '|': append_token(out, TOK_PIPE, "|", 0, line); break;
            case ';': append_token(out, TOK_SEMI, ";", 0, line); break;
            case '!': append_token(out, TOK_CUT,  "!", 0, line); break;
            default: {
                char err[2] = { c, '\0' };
                append_token(out, TOK_ERROR, err, 0, line);
                return -1;
            }
        }
        i++;
    }

    append_token(out, TOK_EOF, "", 0, line);
    return 0;
}

const char *tok_kind_name(TokenKind k)
{
    switch (k) {
        case TOK_ATOM:   return "atom";
        case TOK_VAR:    return "variable";
        case TOK_INT:    return "integer";
        case TOK_LPAREN: return "'('";
        case TOK_RPAREN: return "')'";
        case TOK_COMMA:  return "','";
        case TOK_DOT:    return "'.'";
        case TOK_NECK:   return "':-'";
        case TOK_QUERY:  return "'?-'";
        case TOK_PIPE:   return "'|'";
        case TOK_SEMI:   return "';'";
        case TOK_CUT:    return "'!'";
        case TOK_OP:     return "operator";
        case TOK_EOF:    return "EOF";
        case TOK_ERROR:  return "error";
        default:         return "unknown";
    }
}

/*
 * parser.cpp — Clause and query parser.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/parser.hpp"
#include <cstring>
#include <cassert>
#include <cstdio>

static const Token *peek(const Parser *p)
{
    assert(p != nullptr && p->tokens != nullptr);
    if (p->pos >= p->tokens->count) {
        return &p->tokens->items[p->tokens->count - 1U];
    }
    return &p->tokens->items[p->pos];
}

static const Token *advance(Parser *p)
{
    const Token *t = peek(p);
    if (t->kind != TOK_EOF) { p->pos++; }
    return t;
}

static const Token *expect(Parser *p, TokenKind kind)
{
    const Token *t = peek(p);
    if (t->kind != kind) {
        snprintf(p->error_msg, sizeof(p->error_msg),
                 "line %u: expected %s, got %s '%s'",
                 t->line, tok_kind_name(kind), tok_kind_name(t->kind), t->text);
        return nullptr;
    }
    return advance(p);
}

/* parse_term — parse one term; returns TERM_REF_INVALID on error. */
static TermRef parse_term(Parser *p)
{
    const Token *t   = peek(p);
    TermRef      ref = TERM_REF_INVALID;

    /* integer */
    if (t->kind == TOK_INT) {
        advance(p);
        ref = term_make_int(p->arena, t->int_val);
    }
    /* variable */
    else if (t->kind == TOK_VAR) {
        advance(p);
        VarId vid = VAR_ID_INVALID;
        for (uint32_t k = 0U; k < p->vars->count; ++k) {
            if (strncmp(p->vars->entries[k].name, t->text, VAR_NAME_MAX_LEN) == 0) {
                vid = p->vars->entries[k].id;
                break;
            }
        }
        if (vid == VAR_ID_INVALID) { vid = var_alloc(p->vars, t->text); }
        if (vid == VAR_ID_INVALID) {
            snprintf(p->error_msg, sizeof(p->error_msg),
                     "line %u: variable registry full", t->line);
            return TERM_REF_INVALID;
        }
        ref = term_make_var(p->arena, vid, t->text);
    }
    /* cut */
    else if (t->kind == TOK_CUT) {
        advance(p);
        AtomId aid = atom_intern(p->atoms, "!");
        if (aid == ATOM_ID_INVALID) { return TERM_REF_INVALID; }
        ref = term_make_atom(p->arena, aid);
    }
    /* atom or compound */
    else if (t->kind == TOK_ATOM || t->kind == TOK_OP) {
        const char *name = t->text;
        advance(p);
        AtomId aid = atom_intern(p->atoms, name);
        if (aid == ATOM_ID_INVALID) {
            snprintf(p->error_msg, sizeof(p->error_msg),
                     "line %u: atom table full", t->line);
            return TERM_REF_INVALID;
        }

        if (peek(p)->kind == TOK_LPAREN) {
            TermRef args[TERM_MAX_ARITY];
            uint8_t arity = 0U;
            advance(p);
            if (peek(p)->kind != TOK_RPAREN) {
                for (uint32_t a = 0U; a < static_cast<uint32_t>(TERM_MAX_ARITY); ++a) {
                    TermRef arg = parse_term(p);
                    if (arg == TERM_REF_INVALID) { return TERM_REF_INVALID; }
                    args[arity++] = arg;
                    if (peek(p)->kind != TOK_COMMA) { break; }
                    advance(p);
                }
            }
            if (expect(p, TOK_RPAREN) == nullptr) { return TERM_REF_INVALID; }
            ref = term_make_compound(p->arena, aid, arity, args);
        } else {
            ref = term_make_atom(p->arena, aid);
        }
    }
    else {
        snprintf(p->error_msg, sizeof(p->error_msg),
                 "line %u: unexpected token %s '%s'",
                 t->line, tok_kind_name(t->kind), t->text);
        return TERM_REF_INVALID;
    }

    if (ref == TERM_REF_INVALID) { return TERM_REF_INVALID; }

    /* infix = or \= following any primary term */
    {
        const Token *op = peek(p);
        if (op->kind == TOK_OP &&
            (strncmp(op->text, "=",  2) == 0 ||
             strncmp(op->text, "\\=", 3) == 0)) {
            char   op_name[TOKEN_TEXT_MAX + 1U];
            memcpy(op_name, op->text, TOKEN_TEXT_MAX);
            op_name[TOKEN_TEXT_MAX] = '\0';
            advance(p);

            const TermRef rhs = parse_term(p);
            if (rhs == TERM_REF_INVALID) { return TERM_REF_INVALID; }

            const AtomId op_aid = atom_intern(p->atoms, op_name);
            if (op_aid == ATOM_ID_INVALID) { return TERM_REF_INVALID; }

            const TermRef pair[2] = { ref, rhs };
            ref = term_make_compound(p->arena, op_aid, 2U, pair);
        }
    }
    return ref;
}

static ParseResult parse_term_list(Parser *p, TermRef *out, uint32_t cap,
                                   uint32_t *count)
{
    assert(p != nullptr && out != nullptr && count != nullptr);
    *count = 0U;

    for (uint32_t n = 0U; n < cap; ++n) {
        const TermRef ref = parse_term(p);
        if (ref == TERM_REF_INVALID) { return PARSE_ERR_SYNTAX; }
        out[n] = ref;
        (*count)++;
        if (peek(p)->kind != TOK_COMMA) { break; }
        advance(p);
    }

    if (*count == cap && peek(p)->kind == TOK_COMMA) { return PARSE_ERR_OVERFLOW; }
    return PARSE_OK;
}

int parser_init(Parser *p, const TokenList *tokens, TermArena *arena,
                AtomTable *atoms, VarRegistry *vars)
{
    if (p==nullptr || tokens==nullptr || arena==nullptr ||
        atoms==nullptr || vars==nullptr) { return -1; }
    memset(p, 0, sizeof(Parser));
    p->tokens = tokens;
    p->arena  = arena;
    p->atoms  = atoms;
    p->vars   = vars;
    p->pos    = 0U;
    return 0;
}

ParseResult parser_next_clause(Parser *p, ParsedClause *out)
{
    if (p == nullptr || out == nullptr) { return PARSE_ERR_ARGS; }
    memset(out, 0, sizeof(ParsedClause));
    var_reset(p->vars);

    if (peek(p)->kind == TOK_EOF) { return PARSE_EOF; }

    const TermRef head = parse_term(p);
    if (head == TERM_REF_INVALID) { return PARSE_ERR_SYNTAX; }
    out->head = head;

    if (peek(p)->kind == TOK_NECK) {
        advance(p);
        const ParseResult r = parse_term_list(p, out->body, PARSER_MAX_BODY_GOALS,
                                              &out->body_len);
        if (r != PARSE_OK) { return r; }
    }

    if (expect(p, TOK_DOT) == nullptr) { return PARSE_ERR_SYNTAX; }
    return PARSE_OK;
}

ParseResult parser_query(Parser *p, ParsedQuery *out)
{
    if (p == nullptr || out == nullptr) { return PARSE_ERR_ARGS; }
    memset(out, 0, sizeof(ParsedQuery));
    var_reset(p->vars);

    if (expect(p, TOK_QUERY) == nullptr) { return PARSE_ERR_SYNTAX; }

    const ParseResult r = parse_term_list(p, out->goals, PARSER_MAX_BODY_GOALS,
                                          &out->goal_count);
    if (r != PARSE_OK) { return r; }

    if (expect(p, TOK_DOT) == nullptr) { return PARSE_ERR_SYNTAX; }
    return PARSE_OK;
}

/*
 * database.cpp — Clause database implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/database.hpp"
#include <cstring>
#include <cassert>

static PredEntry *find_pred(Database *db, AtomId functor, uint8_t arity)
{
    assert(db != nullptr);
    for (uint32_t i = 0U; i < db->pred_count; ++i) {
        if (db->preds[i].functor == functor && db->preds[i].arity == arity) {
            return &db->preds[i];
        }
    }
    return nullptr;
}

static PredEntry *find_or_create_pred(Database *db, AtomId functor, uint8_t arity)
{
    PredEntry *e = find_pred(db, functor, arity);
    if (e != nullptr) { return e; }
    if (db->pred_count >= DB_MAX_PREDICATES) { return nullptr; }

    e = &db->preds[db->pred_count];
    memset(e, 0, sizeof(PredEntry));
    e->functor = functor;
    e->arity   = arity;
    e->first   = db->clause_count;
    e->count   = 0U;
    db->pred_count++;
    return e;
}

int db_init(Database *db)
{
    if (db == nullptr) { return -1; }
    memset(db, 0, sizeof(Database));
    return 0;
}

int db_assert_last(Database *db, const ParsedClause *clause, TermArena *arena)
{
    if (db == nullptr || clause == nullptr) { return -1; }
    if (db->clause_count >= DB_MAX_CLAUSES) { return -1; }

    const Term *head_term = term_get(arena, clause->head);
    if (head_term == nullptr) { return -1; }

    AtomId  functor;
    uint8_t arity;

    switch (head_term->kind) {
        case TERM_KIND_ATOM:
            functor = head_term->data.atom_id;
            arity   = 0U;
            break;
        case TERM_KIND_COMPOUND:
            functor = head_term->data.compound.functor;
            arity   = head_term->data.compound.arity;
            break;
        default:
            return -1;
    }

    PredEntry *pred = find_or_create_pred(db, functor, arity);
    if (pred == nullptr) { return -1; }

    const uint32_t insert_pos = pred->first + pred->count;

    for (uint32_t shift = db->clause_count; shift > insert_pos; --shift) {
        db->clauses[shift]    = db->clauses[shift - 1U];
        db->clauses[shift].id = static_cast<ClauseId>(shift + 1U);
    }

    for (uint32_t pi = 0U; pi < db->pred_count; ++pi) {
        if (&db->preds[pi] != pred && db->preds[pi].first >= insert_pos) {
            db->preds[pi].first++;
        }
    }

    StoredClause *sc = &db->clauses[insert_pos];
    memset(sc, 0, sizeof(StoredClause));
    sc->head     = clause->head;
    sc->body_len = clause->body_len;
    sc->id       = static_cast<ClauseId>(insert_pos + 1U);

    assert(clause->body_len <= DB_MAX_BODY_GOALS);
    for (uint32_t bi = 0U; bi < clause->body_len; ++bi) {
        sc->body[bi] = clause->body[bi];
    }

    pred->count++;
    db->clause_count++;
    return 0;
}

int db_retract_first(Database *db, AtomId functor, uint8_t arity)
{
    if (db == nullptr || functor == ATOM_ID_INVALID) { return -1; }

    PredEntry *pred = find_pred(db, functor, arity);
    if (pred == nullptr || pred->count == 0U) { return -1; }

    const uint32_t remove_pos = pred->first;

    for (uint32_t shift = remove_pos; shift + 1U < db->clause_count; ++shift) {
        db->clauses[shift]    = db->clauses[shift + 1U];
        db->clauses[shift].id = static_cast<ClauseId>(shift + 1U);
    }
    db->clause_count--;
    pred->count--;

    for (uint32_t pi = 0U; pi < db->pred_count; ++pi) {
        if (&db->preds[pi] != pred && db->preds[pi].first > remove_pos) {
            db->preds[pi].first--;
        }
    }
    return 0;
}

const PredEntry *db_get_pred(const Database *db, AtomId functor, uint8_t arity)
{
    if (db == nullptr || functor == ATOM_ID_INVALID) { return nullptr; }
    for (uint32_t i = 0U; i < db->pred_count; ++i) {
        if (db->preds[i].functor == functor && db->preds[i].arity == arity) {
            return &db->preds[i];
        }
    }
    return nullptr;
}

const StoredClause *db_get_clause(const Database *db, uint32_t idx)
{
    if (db == nullptr || idx >= db->clause_count) { return nullptr; }
    return &db->clauses[idx];
}

/*
 * unifier.cpp — Robinson unification, iterative implementation.
 * JPL rules: no recursion, bounded work stack, no post-init malloc.
 */

#include "../include/unifier.hpp"
#include <cstring>
#include <cassert>

/* ---- Trail ---------------------------------------------------------------- */

int trail_init(Trail *t)
{
    if (t == nullptr) { return -1; }
    memset(t, 0, sizeof(Trail));
    return 0;
}

uint32_t trail_mark(const Trail *t)
{
    assert(t != nullptr);
    return t->top;
}

void trail_undo(Trail *t, VarRegistry *vars, uint32_t mark)
{
    assert(t != nullptr && vars != nullptr);
    while (t->top > mark) {
        const VarId vid = t->bound[t->top - 1U];
        if (vid != VAR_ID_INVALID) {
            const uint32_t idx = vid - VAR_ID_MIN;
            if (idx < vars->count) {
                VarEntry *e         = &vars->entries[idx];
                e->tag              = TERM_UNBOUND;
                e->value.var_id     = VAR_ID_INVALID;
            }
        }
        t->top--;
    }
}

/* ---- deref ---------------------------------------------------------------- */

TermRef deref(TermRef ref, const TermArena *arena, const VarRegistry *vars)
{
    if (ref == TERM_REF_INVALID) { return TERM_REF_INVALID; }

    for (uint32_t steps = 0U; steps < VAR_REGISTRY_CAPACITY; ++steps) {
        const Term *t = term_get(arena, ref);
        if (t == nullptr) { return TERM_REF_INVALID; }
        if (t->kind != TERM_KIND_VAR) { return ref; }

        const WalkResult wr = var_walk(vars, t->data.var.var_id);
        if (wr.tag == TERM_UNBOUND)  { return ref; }
        if (wr.tag == TERM_TERMREF)  { ref = wr.value.term_ref; continue; }
        if (wr.tag == TERM_VAR) {
            for (uint32_t ni = 0U; ni < arena->count; ++ni) {
                const Term *cand = &arena->nodes[ni];
                if (cand->kind == TERM_KIND_VAR &&
                    cand->data.var.var_id == wr.root_id) {
                    ref = cand->ref;
                    break;
                }
            }
        }
    }
    return ref;
}

/* ---- bind_var ------------------------------------------------------------- */

static int bind_var(VarId vid, TermRef target_ref, const TermArena *arena,
                    VarRegistry *vars, Trail *trail)
{
    assert(vars != nullptr && trail != nullptr && arena != nullptr);
    if (trail->top >= TRAIL_CAPACITY) { return -1; }

    const Term *target = term_get(arena, target_ref);
    if (target == nullptr) { return -1; }

    if (target->kind == TERM_KIND_VAR) {
        if (var_bind_var(vars, vid, target->data.var.var_id) < 0) { return -1; }
    } else {
        if (var_bind_term(vars, vid, target_ref) < 0) { return -1; }
    }

    trail->bound[trail->top] = vid;
    trail->top++;
    return 0;
}

/* ---- unify ---------------------------------------------------------------- */

struct UnifyPair { TermRef a; TermRef b; };

int unify(TermRef a, TermRef b,
          const TermArena *arena, VarRegistry *vars, Trail *trail)
{
    UnifyPair stack[UNIFY_STACK_CAPACITY];
    uint32_t  top = 0U;

    if (arena == nullptr || vars == nullptr || trail == nullptr) { return 0; }

    stack[top++] = { a, b };

    for (uint32_t steps = 0U; steps < UNIFY_STACK_CAPACITY && top > 0U; ++steps) {
        const TermRef ra = deref(stack[--top].a, arena, vars);
        const TermRef rb = deref(stack[top].b,   arena, vars);

        if (ra == rb) { continue; }

        const Term *ta = term_get(arena, ra);
        const Term *tb = term_get(arena, rb);
        if (ta == nullptr || tb == nullptr) { return 0; }

        if (ta->kind == TERM_KIND_VAR) {
            if (bind_var(ta->data.var.var_id, rb, arena, vars, trail) < 0) { return 0; }
            continue;
        }
        if (tb->kind == TERM_KIND_VAR) {
            if (bind_var(tb->data.var.var_id, ra, arena, vars, trail) < 0) { return 0; }
            continue;
        }

        if (ta->kind == TERM_KIND_ATOM && tb->kind == TERM_KIND_ATOM) {
            if (ta->data.atom_id != tb->data.atom_id) { return 0; }
            continue;
        }
        if (ta->kind == TERM_KIND_INT && tb->kind == TERM_KIND_INT) {
            if (ta->data.int_val != tb->data.int_val) { return 0; }
            continue;
        }
        if (ta->kind == TERM_KIND_COMPOUND && tb->kind == TERM_KIND_COMPOUND) {
            const uint8_t arity = ta->data.compound.arity;
            if (ta->data.compound.functor != tb->data.compound.functor) { return 0; }
            if (arity != tb->data.compound.arity) { return 0; }
            if (top + static_cast<uint32_t>(arity) >= UNIFY_STACK_CAPACITY) { return 0; }
            for (uint8_t i = 0U; i < arity; ++i) {
                stack[top++] = { term_arg(arena, ra, i), term_arg(arena, rb, i) };
            }
            continue;
        }
        return 0;
    }

    return (top == 0U) ? 1 : 0;
}

/*
 * builtins.cpp — Built-in predicate implementations.
 * JPL rules: no recursion (term_write uses explicit stack), bounded loops.
 */

#include "../include/builtins.hpp"
#include "../include/parser.hpp"
#include <cstring>
#include <cstdio>
#include <cassert>

/* ---- term_write ----------------------------------------------------------- */

constexpr uint32_t PRINT_STACK_CAP = 512U;

struct PrintFrame { TermRef ref; int after_comma; };

int term_write(TermRef ref, const TermArena *arena,
               const VarRegistry *vars, const AtomTable *atoms)
{
    if (arena == nullptr || vars == nullptr || atoms == nullptr) { return -1; }

    PrintFrame stack[PRINT_STACK_CAP];
    uint32_t   top = 0U;
    stack[top++] = { ref, 0 };

    for (uint32_t steps = 0U; steps < PRINT_STACK_CAP && top > 0U; ++steps) {
        const PrintFrame frame = stack[--top];
        const TermRef    dr    = deref(frame.ref, arena, vars);
        const Term      *t     = term_get(arena, dr);

        if (t == nullptr) { printf("_"); continue; }

        switch (t->kind) {
            case TERM_KIND_ATOM: {
                const char *sp = atom_spelling(atoms, t->data.atom_id);
                printf("%s", sp ? sp : "_");
                break;
            }
            case TERM_KIND_INT:
                printf("%d", static_cast<int>(t->data.int_val));
                break;
            case TERM_KIND_VAR: {
                const WalkResult wr = var_walk(vars, t->data.var.var_id);
                if (wr.tag == TERM_UNBOUND) {
                    const char *vn = t->data.var.name;
                    printf("%s", (vn && vn[0]) ? vn : "_");
                } else if (wr.tag == TERM_ATOM) {
                    const char *sp = atom_spelling(atoms, wr.value.atom_id);
                    printf("%s", sp ? sp : "_");
                } else if (wr.tag == TERM_TERMREF && top < PRINT_STACK_CAP) {
                    stack[top++] = { wr.value.term_ref, 0 };
                } else {
                    printf("_");
                }
                break;
            }
            case TERM_KIND_COMPOUND: {
                const uint8_t arity = t->data.compound.arity;
                const char *fn = atom_spelling(atoms, t->data.compound.functor);
                printf("%s(", fn ? fn : "?");
                if (top + static_cast<uint32_t>(arity) >= PRINT_STACK_CAP) {
                    printf("...)");
                    break;
                }
                for (uint8_t i = 0U; i < arity; ++i) {
                    if (i > 0U) { printf(","); }
                    term_write(term_arg(arena, dr, i), arena, vars, atoms);
                }
                printf(")");
                break;
            }
        }
    }
    return 0;
}

/* ---- Built-in implementations --------------------------------------------- */

static BuiltinResult bi_true(TermRef, SolverEnv *) { return BUILTIN_SUCCEED; }
static BuiltinResult bi_fail(TermRef, SolverEnv *) { return BUILTIN_FAIL;    }
static BuiltinResult bi_cut (TermRef, SolverEnv *) { return BUILTIN_CUT;     }

static BuiltinResult bi_unify(TermRef goal, SolverEnv *env)
{
    const TermRef a = term_arg(env->arena, goal, 0U);
    const TermRef b = term_arg(env->arena, goal, 1U);
    if (a == TERM_REF_INVALID || b == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    const uint32_t mark = trail_mark(&env->trail);
    if (unify(a, b, env->arena, env->vars, &env->trail)) { return BUILTIN_SUCCEED; }
    trail_undo(&env->trail, env->vars, mark);
    return BUILTIN_FAIL;
}

static BuiltinResult bi_not_unify(TermRef goal, SolverEnv *env)
{
    const TermRef a = term_arg(env->arena, goal, 0U);
    const TermRef b = term_arg(env->arena, goal, 1U);
    if (a == TERM_REF_INVALID || b == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    const uint32_t mark = trail_mark(&env->trail);
    const int ok = unify(a, b, env->arena, env->vars, &env->trail);
    trail_undo(&env->trail, env->vars, mark);
    return ok ? BUILTIN_FAIL : BUILTIN_SUCCEED;
}

static BuiltinResult bi_write(TermRef goal, SolverEnv *env)
{
    const TermRef arg = term_arg(env->arena, goal, 0U);
    if (arg == TERM_REF_INVALID) { return BUILTIN_FAIL; }
    term_write(arg, env->arena, env->vars, env->atoms);
    return BUILTIN_SUCCEED;
}

static BuiltinResult bi_nl(TermRef, SolverEnv *) { printf("\n"); return BUILTIN_SUCCEED; }

static BuiltinResult bi_assert(TermRef goal, SolverEnv *env)
{
    const TermRef arg = term_arg(env->arena, goal, 0U);
    if (arg == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    ParsedClause pc;
    memset(&pc, 0, sizeof(ParsedClause));

    const Term *t = term_get(env->arena, deref(arg, env->arena, env->vars));
    if (t == nullptr) { return BUILTIN_FAIL; }

    /* check for ':-'(Head, Body) form — restructured to avoid goto */
    bool is_rule = false;
    if (t->kind == TERM_KIND_COMPOUND && t->data.compound.arity == 2U) {
        const char *fn = atom_spelling(env->atoms, t->data.compound.functor);
        if (fn != nullptr && strncmp(fn, ":-", 3) == 0) {
            pc.head       = term_arg(env->arena, arg, 0U);
            pc.body[0]    = term_arg(env->arena, arg, 1U);
            pc.body_len   = 1U;
            is_rule       = true;
        }
    }
    if (!is_rule) {
        pc.head     = arg;
        pc.body_len = 0U;
    }

    if (db_assert_last(env->db, &pc, env->arena) < 0) { return BUILTIN_FAIL; }
    return BUILTIN_SUCCEED;
}

static BuiltinResult bi_retract(TermRef goal, SolverEnv *env)
{
    const TermRef arg = term_arg(env->arena, goal, 0U);
    if (arg == TERM_REF_INVALID) { return BUILTIN_FAIL; }

    const Term *t = term_get(env->arena, deref(arg, env->arena, env->vars));
    if (t == nullptr) { return BUILTIN_FAIL; }

    AtomId  functor;
    uint8_t arity;
    if (t->kind == TERM_KIND_ATOM) {
        functor = t->data.atom_id; arity = 0U;
    } else if (t->kind == TERM_KIND_COMPOUND) {
        functor = t->data.compound.functor; arity = t->data.compound.arity;
    } else {
        return BUILTIN_FAIL;
    }

    if (db_retract_first(env->db, functor, arity) < 0) { return BUILTIN_FAIL; }
    return BUILTIN_SUCCEED;
}

/* ---- Dispatch table ------------------------------------------------------- */

struct BuiltinEntry { const char *name; uint8_t arity; BuiltinFn fn; };

static const BuiltinEntry BUILTIN_TABLE[] = {
    { "true",    0U, bi_true       },
    { "fail",    0U, bi_fail       },
    { "false",   0U, bi_fail       },
    { "!",       0U, bi_cut        },
    { "=",       2U, bi_unify      },
    { "\\=",     2U, bi_not_unify  },
    { "write",   1U, bi_write      },
    { "nl",      0U, bi_nl         },
    { "assert",  1U, bi_assert     },
    { "assertz", 1U, bi_assert     },
    { "retract", 1U, bi_retract    }
};

constexpr uint32_t BUILTIN_TABLE_SIZE =
    static_cast<uint32_t>(sizeof(BUILTIN_TABLE) / sizeof(BUILTIN_TABLE[0]));

BuiltinFn builtin_lookup(AtomId functor, uint8_t arity, const AtomTable *atoms)
{
    if (functor == ATOM_ID_INVALID || atoms == nullptr) { return nullptr; }
    const char *name = atom_spelling(atoms, functor);
    if (name == nullptr) { return nullptr; }
    for (uint32_t i = 0U; i < BUILTIN_TABLE_SIZE; ++i) {
        if (BUILTIN_TABLE[i].arity == arity &&
            strncmp(BUILTIN_TABLE[i].name, name, ATOM_MAX_LEN) == 0) {
            return BUILTIN_TABLE[i].fn;
        }
    }
    return nullptr;
}

/*
 * solver.cpp — Backtracking SLD resolution engine.
 * JPL rules: no C recursion, bounded stacks, no post-init malloc.
 */

#include "../include/solver.hpp"
#include "../include/builtins.hpp"
#include "../include/log.hpp"
#include <cstring>
#include <cassert>

/* ---- Internal frame types ------------------------------------------------- */

struct GoalStack {
    TermRef  goals[GOAL_STACK_CAPACITY];
    uint32_t top = 0U;
};

struct ChoicePoint {
    uint32_t clause_idx;
    uint32_t clause_end;
    TermRef  goal;
    uint32_t trail_mark;
    uint32_t goal_top;
};

struct ChoiceStack {
    ChoicePoint items[CHOICE_STACK_CAPACITY];
    uint32_t    top = 0U;
};

/* ---- Variable rename map -------------------------------------------------- */

constexpr uint32_t RENAME_MAP_CAP = VAR_REGISTRY_CAPACITY;

struct RenameMap {
    VarId    old_id[RENAME_MAP_CAP];
    VarId    new_id[RENAME_MAP_CAP];
    uint32_t count = 0U;
};

static VarId rename_lookup(const RenameMap *rm, VarId old)
{
    for (uint32_t i = 0U; i < rm->count; ++i) {
        if (rm->old_id[i] == old) { return rm->new_id[i]; }
    }
    return VAR_ID_INVALID;
}

/* rename_term — deep-copy a clause term into env->arena with fresh VarIds. */
static TermRef rename_term(TermRef ref, const TermArena *arena,
                            SolverEnv *env, RenameMap *rm,
                            const AtomTable *)
{
    for (uint32_t step = 0U; step < TERM_ARENA_CAPACITY; ++step) {
        const Term *t = term_get(arena, ref);
        if (t == nullptr) { return TERM_REF_INVALID; }

        switch (t->kind) {
            case TERM_KIND_ATOM:
                return term_make_atom(env->arena, t->data.atom_id);
            case TERM_KIND_INT:
                return term_make_int(env->arena, t->data.int_val);
            case TERM_KIND_VAR: {
                const VarId old   = t->data.var.var_id;
                VarId       fresh = rename_lookup(rm, old);
                if (fresh == VAR_ID_INVALID) {
                    const char *vname = t->data.var.name;
                    fresh = var_alloc(env->vars, vname[0] ? vname : "_");
                    if (fresh == VAR_ID_INVALID) { return TERM_REF_INVALID; }
                    if (rm->count < RENAME_MAP_CAP) {
                        rm->old_id[rm->count] = old;
                        rm->new_id[rm->count] = fresh;
                        rm->count++;
                    }
                }
                return term_make_var(env->arena, fresh, t->data.var.name);
            }
            case TERM_KIND_COMPOUND: {
                TermRef        new_args[TERM_MAX_ARITY];
                const uint8_t  arity = t->data.compound.arity;
                for (uint8_t i = 0U; i < arity; ++i) {
                    new_args[i] = rename_term(term_arg(arena, ref, i),
                                              arena, env, rm, nullptr);
                    if (new_args[i] == TERM_REF_INVALID) { return TERM_REF_INVALID; }
                }
                return term_make_compound(env->arena, t->data.compound.functor,
                                          arity, new_args);
            }
            default:
                return TERM_REF_INVALID;
        }
        break;
    }
    return TERM_REF_INVALID;
}

/* ---- GoalStack helpers ---------------------------------------------------- */

static int gs_push(GoalStack *gs, TermRef g)
{
    if (gs->top >= GOAL_STACK_CAPACITY) { return -1; }
    gs->goals[gs->top++] = g;
    return 0;
}

static TermRef gs_pop(GoalStack *gs)
{
    if (gs->top == 0U) { return TERM_REF_INVALID; }
    return gs->goals[--gs->top];
}

/* ---- Public API ----------------------------------------------------------- */

int solver_env_init(SolverEnv *env,
                    TermArena *arena, TermArena *clause_arena,
                    VarRegistry *vars, VarRegistry *clause_vars,
                    AtomTable *atoms, Database *db)
{
    if (!env || !arena || !clause_arena || !vars || !clause_vars || !atoms || !db) {
        return -1;
    }
    memset(env, 0, sizeof(SolverEnv));
    env->arena        = arena;
    env->clause_arena = clause_arena;
    env->vars         = vars;
    env->clause_vars  = clause_vars;
    env->atoms        = atoms;
    env->db           = db;
    trail_init(&env->trail);
    return 0;
}

uint32_t solve(SolverEnv *env, const TermRef *goals, uint32_t goal_count,
               SolutionCallback cb, void *userdata)
{
    if (!env || !goals || goal_count == 0U || !cb) { return 0U; }

    GoalStack   gs;
    ChoiceStack cs;
    memset(&gs, 0, sizeof(GoalStack));
    memset(&cs, 0, sizeof(ChoiceStack));

    uint32_t solutions = 0U;

    for (uint32_t gi = goal_count; gi > 0U; --gi) {
        if (gs_push(&gs, goals[gi - 1U]) < 0) { return 0U; }
    }

    /* label targets — using C++ style with a flag to avoid cross-init goto */
    bool do_backtrack = false;

    for (uint32_t iter = 0U; iter < 10000000U; ++iter) {

        if (do_backtrack) {
            do_backtrack = false;
            goto backtrack;
        }

        /* SUCCESS */
        if (gs.top == 0U) {
            solutions++;
            if (cb(env, goals, goal_count, userdata) == SOLVE_STOP) {
                return solutions;
            }
            if (cs.top == 0U) { return solutions; }
            goto backtrack;
        }

        /* pop and process next goal */
        {
            const TermRef  goal    = gs_pop(&gs);
            const TermRef  dgoal   = deref(goal, env->arena, env->vars);
            const Term    *gt      = term_get(env->arena, dgoal);
            AtomId         functor = ATOM_ID_INVALID;
            uint8_t        arity   = 0U;

            if (gt == nullptr)                  { goto backtrack; }
            if (gt->kind == TERM_KIND_ATOM)     { functor = gt->data.atom_id; arity = 0U; }
            else if (gt->kind == TERM_KIND_COMPOUND) {
                functor = gt->data.compound.functor;
                arity   = gt->data.compound.arity;
            } else { goto backtrack; }

            /* built-in? */
            {
                BuiltinFn bf = builtin_lookup(functor, arity, env->atoms);
                if (bf != nullptr) {
                    switch (bf(dgoal, env)) {
                        case BUILTIN_SUCCEED: continue;
                        case BUILTIN_FAIL:    goto backtrack;
                        case BUILTIN_CUT:     cs.top = 0U; continue;
                        case BUILTIN_ERROR:   return solutions;
                    }
                }
            }

            /* user-defined clause lookup */
            {
                const PredEntry *pred = db_get_pred(env->db, functor, arity);
                VLOG_SUBSYS("SOLVE", "goal functor=%u arity=%u pred=%s count=%u",
                            functor, arity,
                            pred ? atom_spelling(env->atoms, functor) : "?NONE",
                            pred ? pred->count : 0U);
                if (pred == nullptr || pred->count == 0U) {
                    VLOG_SUBSYS("SOLVE", "%s", "no clauses -> backtrack");
                    goto backtrack;
                }

                if (pred->count > 1U && cs.top < CHOICE_STACK_CAPACITY) {
                    ChoicePoint *cp  = &cs.items[cs.top++];
                    cp->clause_idx   = pred->first + 1U;
                    cp->clause_end   = pred->first + pred->count;
                    cp->goal         = goal;
                    cp->trail_mark   = trail_mark(&env->trail);
                    cp->goal_top     = gs.top;
                }

                {
                    const StoredClause *sc = db_get_clause(env->db, pred->first);
                    if (sc == nullptr) { goto backtrack; }

                    RenameMap rm;
                    memset(&rm, 0, sizeof(RenameMap));
                    const uint32_t mark = trail_mark(&env->trail);

                    const TermRef fresh_head = rename_term(
                        sc->head, env->clause_arena, env, &rm, env->atoms);
                    if (fresh_head == TERM_REF_INVALID) { goto backtrack; }

                    VLOG_SUBSYS("SOLVE", "trying clause head ref=%u", sc->head);
                    if (!unify(dgoal, fresh_head, env->arena, env->vars, &env->trail)) {
                        VLOG_SUBSYS("SOLVE", "%s", "unify failed -> backtrack");
                        trail_undo(&env->trail, env->vars, mark);
                        goto backtrack;
                    }
                    VLOG_SUBSYS("SOLVE", "unified ok, body_len=%u", sc->body_len);

                    for (uint32_t bi = sc->body_len; bi > 0U; --bi) {
                        const TermRef fresh_body = rename_term(
                            sc->body[bi - 1U], env->clause_arena, env, &rm, env->atoms);
                        if (fresh_body == TERM_REF_INVALID ||
                            gs_push(&gs, fresh_body) < 0) {
                            trail_undo(&env->trail, env->vars, mark);
                            goto backtrack;
                        }
                    }
                }
            }
            continue;
        }

        backtrack:
        {
            if (cs.top == 0U) { return solutions; }

            ChoicePoint *cp = &cs.items[cs.top - 1U];
            trail_undo(&env->trail, env->vars, cp->trail_mark);
            gs.top = cp->goal_top;

            if (cp->clause_idx >= cp->clause_end) { cs.top--; goto backtrack; }

            {
                const StoredClause *sc = db_get_clause(env->db, cp->clause_idx);
                const TermRef dgoal = deref(cp->goal, env->arena, env->vars);

                cp->clause_idx++;
                if (cp->clause_idx >= cp->clause_end) { cs.top--; }

                if (sc == nullptr) { goto backtrack; }

                RenameMap rm;
                memset(&rm, 0, sizeof(RenameMap));
                const uint32_t mark = trail_mark(&env->trail);

                const TermRef fresh_head = rename_term(
                    sc->head, env->clause_arena, env, &rm, env->atoms);
                if (fresh_head == TERM_REF_INVALID) { goto backtrack; }

                if (!unify(dgoal, fresh_head, env->arena, env->vars, &env->trail)) {
                    trail_undo(&env->trail, env->vars, mark);
                    goto backtrack;
                }

                for (uint32_t bi = sc->body_len; bi > 0U; --bi) {
                    const TermRef fresh_body = rename_term(
                        sc->body[bi - 1U], env->clause_arena, env, &rm, env->atoms);
                    if (fresh_body == TERM_REF_INVALID ||
                        gs_push(&gs, fresh_body) < 0) {
                        trail_undo(&env->trail, env->vars, mark);
                        goto backtrack;
                    }
                }
            }
            continue;
        }
    }
    return solutions;
}

/*
 * repl.cpp — Read-Eval-Print Loop.
 * JPL rules: no recursion, bounded buffers, no post-init malloc.
 */

#include "include/repl.hpp"
#include "include/lexer.hpp"
#include "include/parser.hpp"
#include "include/solver.hpp"
#include "include/builtins.hpp"

#include <cstdio>
#include <cstring>
#include <cassert>

/* ---- SolutionContext ------------------------------------------------------ */

struct SolutionContext {
    const TermArena   *arena         = nullptr;
    const VarRegistry *vars          = nullptr;
    const AtomTable   *atoms         = nullptr;
    VarId    query_vars[VAR_REGISTRY_CAPACITY]                          = {};
    char     query_var_names[VAR_REGISTRY_CAPACITY][VAR_NAME_MAX_LEN+1U] = {};
    uint32_t query_var_count = 0U;
};

static SolveSignal print_solution(SolverEnv *env,
                                  const TermRef *, uint32_t,
                                  void *userdata)
{
    auto *ctx = static_cast<SolutionContext *>(userdata);
    int any_binding = 0;

    for (uint32_t i = 0U; i < ctx->query_var_count; ++i) {
        const VarId  vid  = ctx->query_vars[i];
        const char  *name = ctx->query_var_names[i];
        if (name[0] == '_' && name[1] == '\0') { continue; }

        for (uint32_t ni = 0U; ni < env->arena->count; ++ni) {
            const Term *t = &env->arena->nodes[ni];
            if (t->kind == TERM_KIND_VAR && t->data.var.var_id == vid) {
                printf("%s = ", name);
                term_write(t->ref, env->arena, env->vars, env->atoms);
                printf("\n");
                any_binding = 1;
                break;
            }
        }
    }

    if (!any_binding) { printf("true"); }
    printf(" ; ");
    fflush(stdout);

    char ch = static_cast<char>(getchar());
    if (ch == ';') {
        while (ch != '\n' && ch != static_cast<char>(EOF)) { ch = static_cast<char>(getchar()); }
        return SOLVE_NEXT;
    }
    if (ch != '\n') {
        while (ch != '\n' && ch != static_cast<char>(EOF)) { ch = static_cast<char>(getchar()); }
    }
    return SOLVE_STOP;
}

/* ---- run_query ------------------------------------------------------------ */

static void run_query(ReplState *s, const char *src)
{
    static TokenList      tokens;
    static SolutionContext ctx;

    memset(&tokens, 0, sizeof(tokens));
    memset(&ctx,    0, sizeof(ctx));

    if (lex(src, &tokens) < 0) { fprintf(stderr, "lex error\n"); return; }

    term_arena_init(&s->query_arena);
    var_registry_init(&s->query_vars);

    Parser parser;
    if (parser_init(&parser, &tokens, &s->query_arena,
                    &s->atoms, &s->query_vars) < 0) { return; }

    ParsedQuery pq;
    if (parser_query(&parser, &pq) != PARSE_OK) {
        fprintf(stderr, "parse error: %s\n", parser.error_msg);
        return;
    }

    ctx.arena           = &s->query_arena;
    ctx.vars            = &s->query_vars;
    ctx.atoms           = &s->atoms;
    ctx.query_var_count = s->query_vars.count;
    for (uint32_t i = 0U; i < s->query_vars.count && i < VAR_REGISTRY_CAPACITY; ++i) {
        ctx.query_vars[i] = s->query_vars.entries[i].id;
        memcpy(ctx.query_var_names[i], s->query_vars.entries[i].name,
               VAR_NAME_MAX_LEN + 1U);
    }

    SolverEnv env;
    if (solver_env_init(&env, &s->query_arena, &s->clause_arena,
                        &s->query_vars, &s->clause_vars,
                        &s->atoms, &s->db) < 0) { return; }

    const uint32_t solutions = solve(&env, pq.goals, pq.goal_count,
                                     print_solution, &ctx);
    if (solutions == 0U) { printf("false.\n"); } else { printf("\n"); }
}

/* ---- load_clauses --------------------------------------------------------- */

static int load_clauses(ReplState *s, const char *src, const char *label)
{
    static TokenList tokens;
    memset(&tokens, 0, sizeof(tokens));

    if (lex(src, &tokens) < 0) {
        fprintf(stderr, "%s: lex error\n", label);
        return -1;
    }

    var_registry_init(&s->clause_vars);

    Parser parser;
    if (parser_init(&parser, &tokens, &s->clause_arena,
                    &s->atoms, &s->clause_vars) < 0) { return -1; }

    int loaded = 0;
    for (;;) {
        ParsedClause clause;
        memset(&clause, 0, sizeof(ParsedClause));
        const ParseResult pr = parser_next_clause(&parser, &clause);
        if (pr == PARSE_EOF) { break; }
        if (pr != PARSE_OK) {
            fprintf(stderr, "%s: parse error: %s\n", label, parser.error_msg);
            return -1;
        }
        if (db_assert_last(&s->db, &clause, &s->clause_arena) < 0) {
            fprintf(stderr, "%s: database full\n", label);
            return -1;
        }
        loaded++;
    }
    return loaded;
}

/* ---- Public API ----------------------------------------------------------- */

int repl_init(ReplState *s)
{
    if (s == nullptr) { return -1; }
    if (atom_table_init(&s->atoms)          < 0) { return -1; }
    if (db_init(&s->db)                     < 0) { return -1; }
    if (term_arena_init(&s->clause_arena)   < 0) { return -1; }
    if (var_registry_init(&s->clause_vars)  < 0) { return -1; }
    if (term_arena_init(&s->query_arena)    < 0) { return -1; }
    if (var_registry_init(&s->query_vars)   < 0) { return -1; }
    return 0;
}

int repl_load_file(ReplState *s, const char *path)
{
    if (s == nullptr || path == nullptr) { return -1; }

    FILE *f = nullptr;
#if defined(_MSC_VER) || defined(__clang_version__)
    if (fopen_s(&f, path, "r") != 0 || f == nullptr) {
#else
    f = fopen(path, "r");
    if (f == nullptr) {
#endif
        fprintf(stderr, "cannot open '%s'\n", path);
        return -1;
    }

    char   buf[1U << 16];
    size_t n = fread(buf, 1U, sizeof(buf) - 1U, f);
    fclose(f);
    buf[n] = '\0';

    const int result = load_clauses(s, buf, path);
    if (result >= 0) {
        printf("%% Loaded %d clause(s) from '%s'\n", result, path);
    }
    return (result >= 0) ? 0 : -1;
}

void repl_run(ReplState *s)
{
    assert(s != nullptr);
    printf("Epilog 0.1  (type 'halt.' to exit, '?- goal.' to query)\n");

    char     line[REPL_LINE_MAX];
    char     src[REPL_LINE_MAX * 8U];
    uint32_t src_len = 0U;

    for (;;) {
        printf(src_len == 0U ? "?- " : "|  ");
        fflush(stdout);

        if (fgets(line, static_cast<int>(REPL_LINE_MAX), stdin) == nullptr) {
            printf("\n");
            break;
        }

        const size_t len = strnlen(line, REPL_LINE_MAX);
        if (src_len + len >= sizeof(src) - 1U) {
            fprintf(stderr, "input too long\n");
            src_len = 0U;
            continue;
        }
        memcpy(src + src_len, line, len);
        src_len += static_cast<uint32_t>(len);
        src[src_len] = '\0';

        /* check for '.' terminator */
        bool complete = false;
        for (uint32_t i = 0U; i < src_len; ++i) {
            if (src[i] == '.' &&
                (i+1U >= src_len || src[i+1U]==' '  || src[i+1U]=='\n' ||
                 src[i+1U]=='\r' || src[i+1U]=='\t' || src[i+1U]=='\0')) {
                complete = true;
                break;
            }
        }
        if (!complete) { continue; }

        if (strncmp(src, "halt.", 5) == 0) { break; }

        if (src_len >= 2U && src[0] == '?' && src[1] == '-') {
            run_query(s, src);
            src_len = 0U;
            continue;
        }

        if (strncmp(src, "consult(", 8) == 0 ||
            strncmp(src, ":- consult(", 11) == 0) {
            const char *open  = strchr(src, '(');
            const char *close = strchr(src, ')');
            if (open != nullptr && close != nullptr && close > open + 1U) {
                char   path[256];
                size_t plen = static_cast<size_t>(close - open - 1U);
                if (plen >= sizeof(path)) { plen = sizeof(path) - 1U; }
                memcpy(path, open + 1U, plen);
                if (path[0] == '\'') {
                    memmove(path, path + 1U, plen - 1U);
                    plen--;
                    if (plen > 0U && path[plen-1U] == '\'') { plen--; }
                }
                path[plen] = '\0';
                repl_load_file(s, path);
            }
            src_len = 0U;
            continue;
        }

        load_clauses(s, src, "<stdin>");
        src_len = 0U;
    }
}

/*
 * main.cpp — Entry point for the Epilog logic programming runtime.
 *
 * Usage:  epilog [--verbose|-v] [file.pl ...]
 */

#include "include/repl.hpp"
#include "include/log.hpp"
#include <cstdio>
#include <cstring>

int g_verbose = 0;

int main(int argc, char *argv[])
{
    static ReplState s;   /* too large for the stack (~8 MB) */

    LOG_INIT(argc, argv);

    if (repl_init(&s) < 0) {
        fprintf(stderr, "epilog: failed to initialise runtime\n");
        return 1;
    }

    VLOG("%s", "runtime initialised");

    for (int i = 1; i < argc; ++i) {
        if (strncmp(argv[i], "--verbose", 10) == 0) { continue; }
        if (strncmp(argv[i], "-v",         3) == 0) { continue; }
        if (argv[i][0] == '-') { continue; }
        VLOG("loading file: %s", argv[i]);
        if (repl_load_file(&s, argv[i]) < 0) { return 1; }
    }

    repl_run(&s);
    return 0;
}
